<?php require_once __DIR__ . '/auth.php'; require_login('admin');$students=one('SELECT COUNT(*) total FROM users WHERE role=\'student\'');$questions=one('SELECT COUNT(*) total FROM questions');$attempts=one('SELECT COUNT(*) total FROM quiz_attempts');$avg=one('SELECT ROUND(AVG(accuracy)) value FROM quiz_attempts');$recent=many('SELECT u.name,s.name subject,qa.score,qa.accuracy,qa.created_at FROM quiz_attempts qa JOIN users u ON u.id=qa.user_id JOIN subjects s ON s.id=qa.subject_id ORDER BY qa.created_at DESC LIMIT 5');$pageTitle='Admin overview';include 'includes/header.php';?><div class="page-head"><div><div class="eyebrow">Operations overview</div><h1>Good morning, admin.</h1><p>Here is the pulse of the SkillRank learning network.</p></div><a class="button button-primary" href="question_form.php">Add question <span>↗</span></a></div><div class="stat-grid"><div class="stat-card"><small>Registered students</small><strong><?=$students['total']?></strong><span class="delta">↑ 12 this month</span></div><div class="stat-card"><small>Question bank</small><strong><?=$questions['total']?></strong><span class="delta">Across 4 subjects</span></div><div class="stat-card"><small>Assessments taken</small><strong><?=$attempts['total']?></strong><span class="delta">↑ 24% this week</span></div><div class="stat-card"><small>Network accuracy</small><strong><?=$avg['value']??0?>%</strong><span class="delta">Healthy signal</span></div></div><section class="panel"><div class="panel-head"><h2>Latest assessment activity</h2><a class="text-link" href="admin_analytics.php">Full analytics →</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Subject</th><th>Score</th><th>Accuracy</th><th>When</th></tr></thead><tbody><?php foreach($recent as $item):?><tr><td><strong><?=e($item['name'])?></strong></td><td><?=e($item['subject'])?></td><td><?=$item['score']?> pts</td><td><span class="pill lime"><?=round($item['accuracy'])?>%</span></td><td class="muted"><?=date('M d, Y',strtotime($item['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section><?php include 'includes/footer.php';?>